///////////////////////////////////////////////////////////////
// Configuration and Constants
///////////////////////////////////////////////////////////////

// Number of noise octaves for fractal Brownian motion (fBM).
#define OCTAVE_COUNT 2

///////////////////////////////////////////////////////////////
// Utility Functions
///////////////////////////////////////////////////////////////

/**
 * Generates a pseudo-random float in the range [0,1], based on the sine of
 * a dot product. This is a common hash function for 2D coordinates.
 *
 * @param coord  2D coordinate input
 * @return       Pseudo-random number in the range [0,1]
 */
float pseudoRandom2D(vec2 coord) {
    return fract(sin(dot(coord, vec2(12.9898, 78.233))) * 43758.5453123);
}

///////////////////////////////////////////////////////////////
// Perlin Noise
///////////////////////////////////////////////////////////////

/**
 * Approximates a single octave of Perlin noise in 2D.
 *
 * @param point  The 2D point in space to sample noise at
 * @return       Noise value for this point, roughly in [0,1]
 */
float perlinNoise2D(vec2 point) 
{
    // Break the point into integer and fractional parts
    vec2 intPart  = floor(point);
    vec2 fracPart = fract(point);

    // Use a smoothstep-like function for fade curve in 2D
    fracPart = fracPart * fracPart * (3.0 - 2.0 * fracPart);

    // Interpolate between four corners of the cell
    float corner00 = pseudoRandom2D(intPart);
    float corner10 = pseudoRandom2D(intPart + vec2(1.0, 0.0));
    float corner01 = pseudoRandom2D(intPart + vec2(0.0, 1.0));
    float corner11 = pseudoRandom2D(intPart + vec2(1.0, 1.0));

    float row0 = mix(corner00, corner10, fracPart.x);
    float row1 = mix(corner01, corner11, fracPart.x);
    float noiseValue = mix(row0, row1, fracPart.y);

    // Optional squaring for a slightly more pronounced curve
    return noiseValue * noiseValue;
}

///////////////////////////////////////////////////////////////
// Fractal Brownian Motion (fBM)
///////////////////////////////////////////////////////////////

/**
 * Computes fractal Brownian motion (fBM) using Perlin noise at multiple scales.
 *
 * @param inputCoord  The 2D coordinate to sample fBM at
 * @return            The resulting fractal noise value
 */
float fractalBrownianMotion(vec2 inputCoord) 
{
    float accumulatedValue = 0.0;  // Accumulates noise over octaves
    float amplitude       = 0.1;   // Starting amplitude for noise
    vec2  offset          = vec2(10.0); // Translation offset per octave

    // Base rotation to "pre-rotate" the coordinate
    mat2 baseRotation = mat2(
        cos(0.5), -sin(0.5),
        sin(0.5),  cos(0.5)
    );
    inputCoord = baseRotation * inputCoord;

    for (int octaveIndex = 0; octaveIndex < OCTAVE_COUNT; ++octaveIndex) 
    {
        // Add Perlin noise multiplied by amplitude
        accumulatedValue += amplitude * perlinNoise2D(inputCoord);

        // Compute an angle that changes over time and by octave index
        float dynamicAngle = iTime * 0.1 * 1.61803 + float(octaveIndex) * 0.5;
        mat2 rotationPerOctave = mat2(
            cos(dynamicAngle), -sin(dynamicAngle),
            sin(dynamicAngle),  cos(dynamicAngle)
        );

        // Slightly change the scale each octave
        float scaleFactor = 1.2 + 0.3 * sin(float(octaveIndex) + iTime);

        // Transform coordinates for next octave
        inputCoord = rotationPerOctave * inputCoord * scaleFactor + offset;

        // Decrease amplitude each octave (mixing two different decay factors)
        amplitude *= mix(0.3, 0.6, sin(float(octaveIndex) + iTime) * 0.5 + 0.5);
    }

    return accumulatedValue;
}

///////////////////////////////////////////////////////////////
// Main Shader Entry Point
///////////////////////////////////////////////////////////////

/**
 * Main fragment shader function for Shadertoy.
 *
 * @param fragColor  Output color for the current fragment
 * @param fragCoord  Input coordinates for the current fragment
 */
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Shadertoy uniforms (provided by environment):
    // iTime       => current time in seconds
    // iResolution => rendering viewport resolution (xyz: width, height, aspect)
    // iMouse      => mouse position (xy: current pixel coords, zw: click pos)
    float time = iTime;
    vec4 mouseData = iMouse / iResolution.x;

    ///////////////////////////////////////////////////////////
    // Compute a normalized device coordinate (NDC) space uv
    // centered around (0,0)
    ///////////////////////////////////////////////////////////
    vec2 uv = fragCoord.xy / iResolution.xy - 0.5;
    uv.x *= iResolution.x / iResolution.y;

    // Zoom out the texture (just an artistic scaling)
    uv *= 5.0;

    ///////////////////////////////////////////////////////////
    // Calculate some distances to create interesting shapes
    ///////////////////////////////////////////////////////////
    float redDistance   = distance(uv, vec2(sin(time), 0.1));
    float greenDistance = distance(uv, vec2(0.0, redDistance));
    float blueDistance  = distance(uv, vec2(redDistance, sin(time)));

    // Combine multiple sinusoidal functions
    float combinedDist = abs(
          sin(redDistance   + time)
        + sin(greenDistance + time)
        + sin(blueDistance  + time)
        + sin(uv.x + time)
        + cos(uv.y + time)
    );

    ///////////////////////////////////////////////////////////
    // Apply a global rotation to uv for base fractal noise
    ///////////////////////////////////////////////////////////
    float rotationAngle = time * 0.05;
    mat2 globalRotation = mat2(
        cos(rotationAngle), -sin(rotationAngle),
        sin(rotationAngle),  cos(rotationAngle)
    );
    vec2 rotatedUV = globalRotation * uv;

    ///////////////////////////////////////////////////////////
    // Sample fractal Brownian motion for additional texture
    ///////////////////////////////////////////////////////////
    float baseNoise      = fractalBrownianMotion(rotatedUV * (1.0 + sin(time) * 0.5));
    float secondaryNoise = fractalBrownianMotion(uv * 2.0 - time * 2.5);

    // Mix the two noises and add to combinedDist
    combinedDist += mix(baseNoise, secondaryNoise, 0.5);

    ///////////////////////////////////////////////////////////
    // Adjust distances by the combined distortion
    ///////////////////////////////////////////////////////////
    redDistance   = pow(redDistance,   combinedDist * 0.5);
    greenDistance = pow(greenDistance, combinedDist * 0.5);
    blueDistance  = pow(blueDistance,  combinedDist * 0.5);

    ///////////////////////////////////////////////////////////
    // Final color assembly
    ///////////////////////////////////////////////////////////
    fragColor = vec4(
        redDistance   + 0.1 * sin(time),
        greenDistance + 0.1 * cos(time),
        blueDistance  + 0.1 * sin(time * 1.5),
        1.0
    );

    // Invert and dim the colors slightly for style
    fragColor.rgb = 1.0 - fragColor.rgb * 0.8;
}
